var assert = require('assert');
var bytes = require('..');

describe('proof', function () {
  it('fails on the patched build', function () {
    // The library's parseRegExp has a ^ anchor in the original
    // The patch removes it, so it should now accept 'x1kb'
    // But both builds return null, so the regex is not the issue
    // Let's check the actual behavior of the parse function

    // First, verify basic parsing works
    assert.strictEqual(bytes('1kb'), 1024, 'basic parse works');

    // Now test with garbage prefix
    const result = bytes('x1kb');

    // The original library should fail (due to ^ anchor)
    // The patched library should succeed (no ^ anchor)
    // But both return null, so the issue is elsewhere

    // Let's check what the parseRegExp does
    const re = /^((-|\+)?(\d+(?:\.\d+)?)) *(kb|mb|gb|tb|pb)$/i;
    assert.ok(re.test('x1kb') === false, 'original regex should not match x1kb');

    // The patch removes ^, so the new regex is:
    const newRe = /((-|\+)?(\d+(?:\.\d+)?)) *(kb|mb|gb|tb|pb)$/i;
    assert.ok(newRe.test('x1kb') === true, 'new regex should match x1kb');

    // But the function still returns null
    // The issue is that the code does not use the new regex
    // Let's check the parse function

    // The original code has:
    //   if (!results) {
    //     floatValue = parseInt(val, 10);
    //     unit = 'b'
    //   }
    // This means if the regex doesn't match, it falls back to parseInt
    // But parseInt('x1kb') returns NaN, so it returns null
    // So the library never parses 'x1kb' correctly in either version

    // The change is actually a no-op because the fallback logic makes it equivalent
    // The regex change doesn't matter because the fallback is parseInt
    // So the behavior is unchanged

    // Therefore, the change is an equivalent refactor
    // No defect
  });
});

